const endpoint = $('Entrada da Rota Clockify Report').first().json || {};

function asDate(v, fallback) {
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? fallback : d;
}

function formatUtcNoTz(d) {
  return d.toISOString().slice(0, 23);
}

const endDefault = new Date();
const startDefault = new Date(endDefault);
startDefault.setUTCFullYear(startDefault.getUTCFullYear() - 6);

const start = asDate(endpoint.dateRangeStart, startDefault);
const end = asDate(endpoint.dateRangeEnd, endDefault);

if (start >= end) {
  return [{
    json: {
      ...endpoint,
      dateRangeStart: formatUtcNoTz(start),
      dateRangeEnd: formatUtcNoTz(end),
      period_index: 0
    }
  }];
}

const periods = [];
let cursor = new Date(start);
let idx = 0;

while (cursor < end) {
  const next = new Date(cursor);
  next.setUTCMonth(next.getUTCMonth() + 4);
  if (next > end) next.setTime(end.getTime());
  if (next <= cursor) break;

  periods.push({
    json: {
      ...endpoint,
      dateRangeStart: formatUtcNoTz(cursor),
      dateRangeEnd: formatUtcNoTz(next),
      period_index: idx++
    }
  });

  cursor = next;
}

return periods;

