const endpoint = $('Entrada da Rota Clockify Report').first().json || {};
const rows = $input.all().flatMap((item) => item.json.timeentries || []);

function toNumberOrNull(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function pickMoneyAmount(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return value;
  if (typeof value === 'object') {
    if (value === null) return null;
    if ('amount' in value) return toNumberOrNull(value.amount);
  }
  return toNumberOrNull(value);
}

if (rows.length === 0) {
  return [{
    json: {
      status: 'success',
      source_flow: 'clockify_report',
      system: endpoint.system || 'clockify_report',
      url: endpoint.url,
      table: endpoint.table,
      id_field: endpoint.id_field,
      primary_key: endpoint.primary_key || endpoint.id_field,
      processed_rows: 0,
      message: 'API retornou sem registros'
    }
  }];
}

return rows.map((r) => ({
  json: {
    record: {
      id: r._id || null,
      description: r.description || null,
      userId: r.userId || null,
      userName: r.userName || null,
      userEmail: r.userEmail || null,
      projectId: r.projectId || null,
      projectName: r.projectName || null,
      projectColor: r.projectColor || null,
      clientId: r.clientId || null,
      clientName: r.clientName || null,
      taskId: r.taskId || null,
      approvalRequestId: r.approvalRequestId || null,
      time_start: r.timeInterval?.start || null,
      time_end: r.timeInterval?.end || null,
      time_duration: toNumberOrNull(r.timeInterval?.duration),
      time_timezone: r.timeInterval?.timeZone || null,
      time_zoned_start: r.timeInterval?.zonedStart || null,
      time_zoned_end: r.timeInterval?.zonedEnd || null,
      time_off_start: toNumberOrNull(r.timeInterval?.offStart),
      time_off_end: toNumberOrNull(r.timeInterval?.offEnd),
      billable: r.billable ?? null,
      type: r.type || null,
      isLocked: r.isLocked ?? null,
      currency: r.currency || null,
      amount: pickMoneyAmount(r.amount),
      rate: pickMoneyAmount(r.rate),
      earnedAmount: pickMoneyAmount(r.earnedAmount),
      earnedRate: pickMoneyAmount(r.earnedRate),
      costAmount: pickMoneyAmount(r.costAmount),
      costRate: pickMoneyAmount(r.costRate)
    }
  }
}));

const endpoint = $('Entrada da Rota Clockify Report').first().json || {};
const table = endpoint.table;
const idField = endpoint.id_field;

function toSql(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number') return String(v);
  if (typeof v === 'boolean') return v ? 'true' : 'false';

  const s = (typeof v === 'object') ? JSON.stringify(v) : String(v);
  const q = String.fromCharCode(39);
  return q + s.split(q).join(q + q).split('$').join('$ ') + q;
}

const records = $input
  .all()
  .map((item) => item.json?.record)
  .filter((r) => r && typeof r === 'object' && !Array.isArray(r));

if (!table || !idField || records.length === 0) {
  return [{ json: { upsert_query: 'SELECT 0::int AS affected_rows;' } }];
}

const fieldSet = new Set();
for (const rec of records) {
  for (const key of Object.keys(rec)) {
    if (!key.startsWith('_') && !key.startsWith('$')) fieldSet.add(key);
  }
}

const fields = Array.from(fieldSet);
if (!fields.includes(idField)) fields.unshift(idField);

if (fields.length === 0) {
  return [{ json: { upsert_query: 'SELECT 0::int AS affected_rows;' } }];
}

const columns = fields.join(', ');
const updateFields = fields.filter((f) => f !== idField);
const updates = (updateFields.length > 0)
  ? updateFields.map((f) => `${f}=EXCLUDED.${f}`).join(', ')
  : `${idField}=EXCLUDED.${idField}`;

const valuesList = records
  .map((rec) => `(${fields.map((f) => toSql(rec[f])).join(', ')})`)
  .join(', ');

const upsertQuery = `WITH upserted AS (INSERT INTO raw_data.${table} (${columns}) VALUES ${valuesList} ON CONFLICT (${idField}) DO UPDATE SET ${updates} RETURNING 1) SELECT COUNT(*)::int AS affected_rows FROM upserted;`;
return [{ json: { upsert_query: upsertQuery } }];

const rows = Array.isArray($json.rows) ? $json.rows : [];
const endpoint = $('Entrada da Rota Clockify Report').first().json || {};
const processedRows = rows.reduce((acc, r) => acc + Number(r.affected_rows || 0), 0);

return [{
  json: {
    status: 'success',
    source_flow: 'clockify_report',
    system: endpoint.system || 'clockify_report',
    url: endpoint.url,
    table: endpoint.table,
    id_field: endpoint.id_field,
    primary_key: endpoint.primary_key || endpoint.id_field,
    processed_rows: processedRows,
    message: 'UPSERT concluido com sucesso'
  }
}];

const errors = Array.isArray($json.errors) ? $json.errors : [];
const first = errors[0] || {};
const endpoint = $('Entrada da Rota Clockify Report').first().json || {};

return [{
  json: {
    status: 'error',
    stage: 'database',
    source_flow: 'clockify_report',
    system: endpoint.system || 'clockify_report',
    url: endpoint.url,
    table: endpoint.table,
    id_field: endpoint.id_field,
    primary_key: endpoint.primary_key || endpoint.id_field,
    error: {
      message: first.message || first.error || 'Falha no UPSERT Clockify Report',
      total_errors: errors.length,
      sample: first
    }
  }
}];
